        OwnerUserId = ownerUserId;
        LocationDescription = locationDescription;
        SpaceType = spaceType;
        CapacityUnits = capacityUnits;
        IsAvailable = true;
    }

    public void LinkSmartLock(Guid smartLockId)
    {
        LinkedSmartLockId = smartLockId;
    }

